/**
 * File ownership (plan 5 P3.0): Generator-owned files start with the
 * `// Auto Generated By Generator - …` header. Anything else is user-owned and is never overwritten —
 * neither by backend generation nor by saving a model from the Generator UI.
 */
const GENERATOR_HEADER = /^\s*\/\/ Auto Generated By Generator\b/;

export function isGeneratorOwnedSource(content: string): boolean {
  return GENERATOR_HEADER.test(content);
}

export const USER_OWNED_FILE_MESSAGE =
  'Bu dosya Generator tarafından üretilmemiş (Generator başlığı yok); elle yazılmış dosyanın üzerine yazılmaz.';
